```java package algorithm.loadbalance;
import com.alibaba.fastjson.JSON;
import java.util.*;
/**
@author Cao Xuan
@date 2021/3/21 20:04
@update 2021/5/5 */ public class LoadBalanceDemo {
private final List serverList = new ArrayList&lt;&gt;();
/**
client -&gt; server */ private final Map&lt;Client, Server&gt; clientServerMap = new HashMap&lt;&gt;(); /**
&lt;&mdash;head&mdash;tail&mdash;&gt; &lt;&mdash;light&mdash;weight&mdash;&gt; &lt;&mdash;former&mdash;latter&ndash;&gt; */ @Deprecated private void sort() { for (int i = serverList.size() - 1; i &gt; 0; i&ndash;) { for (int j = i - 1; j &gt; -1; j&ndash;) { Server latter = new Server(serverList.get(i)); Server former = new Server(serverList.get(j)); if (latter.getCurrentLoad().size() &gt; former.getCurrentLoad().size()) { serverList.set(i, former); serverList.set(j, latter); } } } System.out.println(&ldquo;sorting&hellip;&rdquo;); } /**
&lt;&mdash;head&mdash;tail&mdash;&gt; &lt;&mdash;light&mdash;weight&mdash;&gt; &lt;&mdash;former&mdash;latter&ndash;&gt; */ private void leafShift() { int size = serverList.size(); for (int i = size - 2; i &gt;= 0; i&ndash;) { Server latter = new Server(serverList.get(size - 1)); Server former = new Server(serverList.get(i)); if (latter.getCurrentLoad().size() &gt; former.getCurrentLoad().size()) { serverList.set(size - 1, former); serverList.set(i, latter); System.out.println(&ldquo;leaf shift&rdquo;); } } } private void rightShift(int index) { int size = serverList.size(); for (int i = index + 1; i &lt; size; i++) { Server former = new Server(serverList.get(index)); Server latter = new Server(serverList.get(i)); if (former.getCurrentLoad().size() &lt; latter.getCurrentLoad().size()) { serverList.set(i, former); serverList.set(index, latter); System.out.println(&ldquo;right shift&rdquo;); } } }
public Server addClient(Client client) { if (serverList.size() &gt; 0) { Server server = new Server(serverList.get(serverList.size() - 1)); String serverName = server.getName(); serverList.get(serverList.size() - 1).updateCurrentLoad(client); System.out.println(&ldquo;Hi,[&rdquo; + client.getUsername() + &ldquo;]. Assign [&rdquo; + serverName + &ldquo;] to you&rdquo;); leafShift(); show(); return server; } else { System.err.println(&ldquo;no server&rdquo;); return null; } }
public void removeClient(String clientName) { Server server = clientServerMap.get(new Client(clientName)); int index = serverList.indexOf(server); if (-1 != index) { server.currentLoad.remove(new Client(clientName)); rightShift(index); System.out.println(&ldquo;remove a client [&rdquo; + clientName + &ldquo;]&rdquo;); } else { System.err.println(&ldquo;index = -1&rdquo;); }
show(); }
public void addServer(String name) { Server server = new Server(name, new HashSet&lt;&gt;()); if (serverList.contains(server)) { System.err.println(&ldquo;The server [&rdquo; + name + &ldquo;] already exists&rdquo;); show(); return; } serverList.add(server); System.out.println(&ldquo;add a server [&rdquo; + name + &ldquo;]&rdquo;); show(); }
public void removeServer(String serverName) { serverList.remove(new Server(serverName)); System.out.println(&ldquo;add a server [&rdquo; + serverName + &ldquo;]&rdquo;); show(); }
private static class Client {
private String username; public Client(String username) { this.username = username; } public String getUsername() { return username; } public void setUsername(String username) { this.username = username; } @Override public boolean equals(Object obj) { if (!(obj instanceof Client)) { return false; } Client client = (Client) obj; return this.getUsername().equals(client.getUsername()); } @Override public int hashCode() { return Objects.hash(username); } @Override public String toString() { return JSON.toJSONString(this); } }
private static class Server {
private String name; private Set&lt;Client&gt; currentLoad; public Server(String name) { this.name = name; } public Server(Server server) { this.name = server.name; this.currentLoad = server.currentLoad; } public Server(String name, Set&lt;Client&gt; currentLoad) { this.name = name; this.currentLoad = currentLoad; } public String getName() { return name; } public void setName(String name) { this.name = name; } public Set&lt;Client&gt; getCurrentLoad() { return currentLoad; } public void setCurrentLoad(Set&lt;Client&gt; currentLoad) { this.currentLoad = currentLoad; } public void updateCurrentLoad(Client client) { this.currentLoad.add(client); } @Override public boolean equals(Object obj) { if (!(obj instanceof Server)) { return false; } Server server = (Server) obj; return this.getName().equals(server.getName()); } @Override public String toString() { return JSON.toJSONString(this); } }
public static void main(String[] args) {
LoadBalanceDemo loadBalanceDemo = new LoadBalanceDemo(); System.out.println(&quot;---------------USAGE--------------&quot;); System.out.println(&quot;Add a server: [s+${serverName}]&quot;); System.out.println(&quot;Add a client: [c+${clientName}]&quot;); System.out.println(&quot;Remove a server: [s-${serverName}]&quot;); System.out.println(&quot;Remove a client: [c-${clientName}]&quot;); System.out.println(&quot;Show Current Load: [show]&quot;); System.out.println(&quot;---------------USAGE--------------&quot;); while (true) { System.out.println(&quot;ready&quot;); System.out.println(); Scanner scanner = new Scanner(System.in); String s = scanner.next(); if (&quot;show&quot;.equals(s)) { loadBalanceDemo.show(); } else if (s.startsWith(&quot;c+&quot;)) { String clientName = s.substring(2); Client client = new Client(clientName); Server server = loadBalanceDemo.addClient(client); loadBalanceDemo.clientServerMap.put(client, server); } else if (s.startsWith(&quot;s+&quot;)) { String serverName = s.substring(2); loadBalanceDemo.addServer(serverName); } else if (s.startsWith(&quot;c-&quot;)) { String clientName = s.substring(2); loadBalanceDemo.removeClient(clientName); } else if (s.startsWith(&quot;s-&quot;)) { String serverName = s.substring(2); loadBalanceDemo.removeServer(serverName); } else { System.out.println(&quot;?&quot;); } System.out.println(&quot;----------------------------------&quot;); } }
private void show() { System.out.println(&ldquo;current load &quot; + serverList); } }
